;; S5A2 oracle probe: namespace/VAR surface (create-ns, in-ns, ns-name,
;; the-ns, find-ns, remove-ns, alias, ns-map family, intern, declare,
;; ns-unmap, ns-unalias). Fixture ns fx35 is built by fx35-setup.
;; Exit 0 (caught; chains printed).
(defn tx [label f]
  (println label "=>" (pr-str (try (f) (catch Throwable t
    (loop [t t acc []] (if t (recur (.getCause t) (conj acc (str (.getName (class t)) " | " (.getMessage t)))) acc)))))))
(tx "create-ns-fresh" #(let [n (create-ns 'cns35fresh)] [(class n) (ns-name n) (str n) (identical? n (find-ns 'cns35fresh))]))
(tx "create-ns-existing" #(let [a (create-ns 'cns35exist) b (create-ns 'cns35exist)] [(identical? a b) (ns-name b)]))
(tx "create-ns-ns-arg" #(ns-name (create-ns (create-ns 'cns35nsarg))))
(tx "in-ns-fresh" #(let [o *ns*] (try (let [r (in-ns 'inns35fresh)] [(class r) (ns-name r) (ns-name *ns*) (identical? r *ns*)]) (finally (in-ns (ns-name o))))))
(tx "in-ns-existing" #(do (create-ns 'inns35exist) (let [o *ns*] (try (let [r (in-ns 'inns35exist)] [(ns-name r) (identical? r *ns*) (identical? r (find-ns 'inns35exist))]) (finally (in-ns (ns-name o)))))))
(tx "create-vs-in-ns-refers" #(let [c (count (ns-refers (create-ns 'cmp35c))) o *ns*] (try (do (in-ns 'cmp35i) [c (count (ns-refers (the-ns 'cmp35i)))]) (finally (in-ns (ns-name o))))))
(tx "ns-name-ns" #(let [n (create-ns 'nname35)] [(ns-name n) (class (ns-name n))]))
(tx "ns-name-sym" #(do (create-ns 'nname35s) (ns-name 'nname35s)))
(tx "ns-name-missing" #(ns-name 'nname35missing))
(tx "the-ns-sym" #(do (create-ns 'tns35a) (let [n (the-ns 'tns35a)] [(ns-name n) (identical? n (find-ns 'tns35a))])))
(tx "the-ns-string" #(do (create-ns 'tns35b) (the-ns "tns35b")))
(tx "the-ns-ns-arg" #(let [n (create-ns 'tns35c)] (identical? n (the-ns n))))
(tx "the-ns-missing" #(the-ns 'tns35missing))
(tx "find-ns-hit" #(do (create-ns 'fns35a) (ns-name (find-ns 'fns35a))))
(tx "find-ns-miss" #(find-ns 'fns35missing))
(tx "find-ns-nil" #(find-ns nil))
(tx "remove-ns-hit" #(do (create-ns 'rmns35hit) (let [r (remove-ns 'rmns35hit)] [(ns-name r) (find-ns 'rmns35hit)])))
(tx "remove-ns-miss" #(remove-ns 'rmns35missing))
(tx "remove-ns-current" #(let [o *ns*] (try (do (create-ns 'rmns35cur) (in-ns 'rmns35cur) (let [cur *ns* r (remove-ns 'rmns35cur)] [(ns-name r) (find-ns 'rmns35cur) (identical? cur *ns*) (ns-name *ns*)])) (finally (in-ns (ns-name o))))))
(tx "alias-fresh" #(do (create-ns 'al35target) (try (do (alias 'al35fresh 'al35target) (let [m (ns-aliases *ns*)] [(contains? m 'al35fresh) (ns-name (get m 'al35fresh))])) (finally (ns-unalias *ns* 'al35fresh)))))
(tx "alias-shadow" #(do (create-ns 'sh35real) (intern 'sh35real 'v 1) (require 'clojure.string) (try (do (alias 'sh35real 'clojure.string) [(ns-name (get (ns-aliases *ns*) 'sh35real)) (ns-name (find-ns 'sh35real))]) (finally (ns-unalias *ns* 'sh35real)))))
(tx "alias-bad-target" #(alias 'al35bad 'al35missing-target))
(tx "fx35-setup" #(do (create-ns 'fx35) (intern 'fx35 'pub35 1) (alter-meta! (intern 'fx35 'priv35 2) assoc :private true) (require 'clojure.string) (binding [*ns* (the-ns 'fx35)] [(import 'java.util.ArrayList) (refer 'clojure.string :only '[join]) (alias 's35 'clojure.string)])))
(tx "ns-aliases-fx" #(into (sorted-map) (map (fn [[k v]] [k (ns-name v)]) (ns-aliases 'fx35))))
(tx "ns-map-fx" #(let [m (ns-map 'fx35)] [(count m) (into (sorted-map) (select-keys m '[pub35 priv35 join ArrayList String Object s35])) (contains? m 's35)]))
(tx "ns-interns-fx" #(into (sorted-map) (ns-interns 'fx35)))
(tx "ns-publics-fx" #(into (sorted-map) (ns-publics 'fx35)))
(tx "ns-refers-fx" #(into (sorted-map) (ns-refers 'fx35)))
(tx "ns-imports-fx" #(let [m (ns-imports 'fx35)] [(count m) (get m 'ArrayList) (get m 'String) (get m 'Object) (sort (distinct (map (fn [v] (str (class v))) (vals m))))]))
(tx "intern-2-arity" #(do (create-ns 'in35) (let [v (intern 'in35 'two35)] [(str v) (var? v) (bound? v)])))
(tx "intern-3-arity" #(do (create-ns 'in35) (let [v (intern 'in35 'three35 42)] [(str v) @v (bound? v)])))
(tx "intern-ns-arg" #(do (create-ns 'in35) (let [v (intern (the-ns 'in35) 'via-ns 9)] [(str v) @v])))
(tx "intern-overwrite" #(do (create-ns 'in35) (let [v1 (intern 'in35 'over35 1) v2 (intern 'in35 'over35 2)] [(identical? v1 v2) @v1 @v2 (str v2)])))
(tx "intern-missing-ns" #(intern 'in35missing 'x 1))
(tx "declare-visible" #(try (do (declare dec35a dec35b) [(contains? (ns-interns *ns*) 'dec35a) (contains? (ns-publics *ns*) 'dec35b) (let [v (ns-resolve *ns* 'dec35a)] [(var? v) (bound? v) (str v)])]) (finally (ns-unmap *ns* 'dec35a) (ns-unmap *ns* 'dec35b))))
(tx "ns-unmap-effect" #(do (intern *ns* 'unm35 1) [(contains? (ns-interns *ns*) 'unm35) (ns-unmap *ns* 'unm35) (contains? (ns-interns *ns*) 'unm35) (ns-unmap *ns* 'unm35miss)]))
(tx "ns-unalias-effect" #(do (create-ns 'una35t) (alias 'una35a 'una35t) [(contains? (ns-aliases *ns*) 'una35a) (ns-unalias *ns* 'una35a) (contains? (ns-aliases *ns*) 'una35a)]))
(tx "ns-print" #(pr-str [(the-ns 'user) (create-ns 'p35print)]))
(tx "ns-map-missing" #(ns-map 'p35missing-ns))
(tx "all-ns-shape" #(do (create-ns 'p35all-b) (create-ns 'p35all-a) (let [names (map ns-name (all-ns))] [(boolean (some #{'p35all-a 'p35all-b} names)) (= names (sort names)) (count (filter #{'p35all-a} names))])))
(tx "resolve-qualified" #(do (create-ns 'p35r) (intern 'p35r 'v 1) (str (resolve 'p35r/v))))
(tx "resolve-miss" #(do (create-ns 'p35r) (resolve 'p35r/missing-v)))
(tx "resolve-unqualified" #(do (intern *ns* 'p35u 1) (let [r (str (resolve 'p35u))] (ns-unmap *ns* 'p35u) r)))
(tx "resolve-class" #(resolve 'String))
(tx "ns-resolve-ns-arg" #(do (create-ns 'p35n) (intern 'p35n 'w 2) [(str (ns-resolve 'p35n 'w)) (ns-resolve 'p35n 'missing)]))
(tx "ns-resolve-missing-ns" #(ns-resolve 'p35missing-ns 'x))
(tx "find-ns-ns-arg" #(find-ns (the-ns 'user)))
(tx "create-ns-string" #(create-ns "p35str"))
(tx "in-ns-ns-arg" #(let [o *ns*] (try (ns-name (in-ns (the-ns 'user))) (finally (in-ns (ns-name o))))))
(tx "remove-ns-ns-arg" #(do (create-ns 'p35rm) (ns-name (remove-ns (the-ns 'p35rm)))))
(tx "alias-ns-target" #(try (do (alias 'p35al (the-ns 'user)) (ns-name (get (ns-aliases *ns*) 'p35al))) (finally (ns-unalias *ns* 'p35al))))
(tx "refer-direct" #(do (create-ns 'p35f) (binding [*ns* (the-ns 'p35f)] [(refer 'clojure.string :only '[join]) (str (get (ns-refers *ns*) 'join))])))
(tx "refer-clojure-exclude" #(do (create-ns 'p35g) (binding [*ns* (the-ns 'p35g)] [(refer-clojure :exclude '[map]) (contains? (ns-refers *ns*) 'map) (contains? (ns-refers *ns*) 'dec)])))
(tx "ns-unmap-sym-ns" #(do (create-ns 'p35u2) (intern 'p35u2 'x 1) [(ns-unmap 'p35u2 'x) (contains? (ns-interns 'p35u2) 'x)]))
(tx "ns-unalias-sym-ns" #(do (create-ns 'p35u3) (binding [*ns* (the-ns 'p35u3)] (alias 'a33 'clojure.string)) [(ns-unalias 'p35u3 'a33) (contains? (ns-aliases 'p35u3) 'a33)]))
(tx "alias-overwrite" #(do (create-ns 'p35o1) (create-ns 'p35o2) (try (do (alias 'p35oo 'p35o1) (alias 'p35oo 'p35o2) (ns-name (get (ns-aliases *ns*) 'p35oo))) (finally (ns-unalias *ns* 'p35oo)))))
(tx "resolve-ns-arg" #(resolve (the-ns 'user)))
(tx "ns-name-removed" #(let [n (create-ns 'p35gone)] (remove-ns 'p35gone) (ns-name n)))
(tx "alias-same-twice" #(do (create-ns 'p35s1) (try (do (alias 'p35ss 'p35s1) (alias 'p35ss 'p35s1)) (finally (ns-unalias *ns* 'p35ss)))))
(tx "refer-twice" #(do (create-ns 'p35f2) (binding [*ns* (the-ns 'p35f2)] [(refer 'clojure.string :only '[join]) (refer 'clojure.string :only '[join]) (str (get (ns-refers *ns*) 'join))])))
(tx "refer-shadow" #(do (create-ns 'p35f3) (binding [*ns* (the-ns 'p35f3)] (intern 'p35f3 'join 99) [(refer 'clojure.string :only '[join]) (str (get (ns-map *ns*) 'join)) @(get (ns-map *ns*) 'join)])))
(tx "create-ns-nil" #(create-ns nil))
(tx "remove-ns-nil" #(remove-ns nil))
(tx "in-ns-nil" #(let [o *ns*] (try (in-ns nil) (finally (in-ns (ns-name o))))))
(tx "resolve-nil" #(resolve nil))
(tx "intern-nil-name" #(do (create-ns 'p35nn) (intern 'p35nn nil 1)))
(tx "alias-nil-name" #(alias nil 'user))
(tx "alias-string-name" #(do (alias "s35x" 'user) (let [r [(some? (get (ns-aliases *ns*) "s35x")) (ns-unalias *ns* "s35x")]] (ns-unalias *ns* "s35x") (conj r (contains? (ns-aliases *ns*) "s35x")))))
(tx "refer-qualified-only" #(do (create-ns 'p35q) (binding [*ns* (the-ns 'p35q)] (refer 'clojure.string :only '[a/b]))))
(tx "intern-qualified-name" #(do (create-ns 'p35qn) (intern 'p35qn 'a/b 1)))
(tx "name-num" #(name 5))
(tx "find-ns-num" #(find-ns 5))
(tx "find-ns-kw" #(find-ns :kw35))
(tx "create-ns-num" #(create-ns 5))
(tx "name-nil" #(name nil))
(tx "all-ns-pr" #(let [s (pr-str (all-ns))] [(subs s 0 1) (subs s (dec (count s))) (type (all-ns))]))
(tx "ns-unmap-nil" #(ns-unmap *ns* nil))
(tx "ns-unalias-nil" #(ns-unalias *ns* nil))
(tx "arity-intern-1" #(intern 'p35ar))
(tx "arity-thens-0" #(the-ns))
